"""Source files that are not the project's own code, recognised by their content.

Both steps use this check: step 1 does not count such files, step 2 neither
formats nor lints them. A file is left out if

1. it is generated: the comment block at its start carries a generator's
   marker. Code generators announce themselves there, whatever the framework:
   "This file was automatically generated by SWIG", "Generated by the protocol
   buffer compiler.  DO NOT EDIT!", "// Code generated ... DO NOT EDIT." (Go),
   "<auto-generated>" (.NET), "@generated" (rustfmt, Meta), ...
   Only comments before the first line of code count, so a generator's own
   source, which writes such a header as a string, stays the project's code;
2. it is minified JavaScript: average line length above 110 characters
   (GitHub Linguist, generated.rb `minified_files?`);
3. it is compiled JavaScript: a source map comment in its last two lines
   (GitHub Linguist, generated.rb `has_source_map?`);
4. it is XML with a TypeScript extension: Qt translation files (.ts), tilesets
   of the Tiled map editor (.tsx).
"""

from __future__ import annotations

import re
from pathlib import Path

HEAD_BYTES = 16 * 1024
HEADER_MAX_LINES = 60

# Extensions shared with XML formats.
XML_SUFFIXES = (".ts", ".tsx")
XML_START = (b"<?xml", b"<!DOCTYPE", b"<TS", b"<tileset")

JAVASCRIPT_SUFFIXES = (".js", ".mjs", ".cjs")
MINIFIED_LINE_LENGTH = 110
_SOURCE_MAP = re.compile(r"^/[*/][#@] source(?:Mapping)?URL|sourceURL=")

_LINE_COMMENTS = ("//", "--")
_BLOCK_COMMENTS = (("/*", "*/"), ('"""', '"""'), ("'''", "'''"), ("<!--", "-->"), ("{-", "-}"))

_GENERATED_MARKER = re.compile(
    r"@generated\b"  # Meta's convention, rustfmt's marker
    r"|<auto-?generated\b"  # .NET (Roslyn)
    r"|\bcode generated\b"  # Go: "Code generated ... DO NOT EDIT."
    r"|\b(?:automatically|auto|machine)[- ]?generated\b"
    r"|\bdo not (?:edit|modify|make (?:any )?changes)\b"
    r"|\bchanges?\b[^\n]{0,60}\bwill be lost\b"  # Qt moc/uic, gRPC, .NET
    r"|^[^\w\n]*generated (?:by|from|with|using)\b"  # a comment line starting so
    r"|\bthis (?:file|code|class|module|header|source) (?:is|was|has been) (?:\w+ )?generated\b",
    re.IGNORECASE | re.MULTILINE,
)


def exclusion_reason(path: Path) -> str | None:
    """Why the file is not the project's own code (see the module docstring), or None."""
    suffix = path.suffix.lower()
    whole = suffix in JAVASCRIPT_SUFFIXES  # the JavaScript rules need the whole file
    try:
        with path.open("rb") as handle:
            data = handle.read() if whole else handle.read(HEAD_BYTES)
    except OSError:
        return None

    if suffix in XML_SUFFIXES and data.lstrip(b"\xef\xbb\xbf \t\r\n").startswith(XML_START):
        return "XML, not TypeScript"
    text = data.decode("utf-8", errors="replace").lstrip("﻿")
    lines = text.splitlines()
    if marker := generated_marker(lines):
        return f"generated: {marker}"
    if whole and lines:
        average = (len(text) - text.count("\n") - text.count("\r")) // len(lines)
        if average > MINIFIED_LINE_LENGTH:
            return f"minified: average line length {average}"
        last = [line.strip() for line in lines if line.strip()][-2:]
        if any(_SOURCE_MAP.search(line) for line in last):
            return "compiled: source map comment"
    return None


def generated_marker(lines: list[str]) -> str | None:
    """The comment line with a generator's marker in the file's leading comments."""
    for line in header_comment(lines):
        if _GENERATED_MARKER.search(line):
            text = line.strip().lstrip("/*#-<! \t").rstrip("*/-> \t")
            return text if len(text) <= 100 else text[:97] + "..."
    return None


def header_comment(lines: list[str]) -> list[str]:
    """The comment lines at the start of a file, up to the first line of code."""
    comment: list[str] = []
    closing: str | None = None
    for line in lines[:HEADER_MAX_LINES]:
        text = line.strip()
        if closing is not None:
            comment.append(text)
            if closing in text:
                closing = None
            continue
        if not text:
            continue
        if text.startswith(_LINE_COMMENTS) or _is_hash_comment(text):
            comment.append(text)
            continue
        block = next(((start, end) for start, end in _BLOCK_COMMENTS if text.startswith(start)), None)
        if block is None:
            break  # first line of code
        comment.append(text)
        start, end = block
        if end not in text[len(start):]:
            closing = end
    return comment


def _is_hash_comment(text: str) -> bool:
    """`# ...` comments and shebangs; not C preprocessor lines like `#include`."""
    return text == "#" or text[:2] in ("# ", "#!", "##", "#\t")
